const char *sensor_state_id(sensor_state_t state) {
    switch (state) {
    case SENSOR_STATE_OFF: return "sensor.Off";
    case SENSOR_STATE_CALIBRATING: return "sensor.Calibrating";
    case SENSOR_STATE_READY: return "sensor.Ready";
    case SENSOR_STATE_FAILED: return "sensor.Failed";
    }
    return "?";
}

const char *sensor_event_name(sensor_event_t event) {
    switch (event) {
    case SENSOR_EV_START: return "START";
    case SENSOR_EV_CALIBRATED: return "CALIBRATED";
    case SENSOR_EV_CAL_TIMEOUT: return "CAL_TIMEOUT";
    }
    return "?";
}

bool sensor_event_from_name(const char *name, sensor_event_t *event) {
    for (int i = 0; i < SENSOR_EVENT_COUNT; i++)
        if (!strcmp(sensor_event_name((sensor_event_t)i), name)) {
            *event = (sensor_event_t)i;
            return true;
        }
    return false;
}

